// План specs/modals.md, 2.1 (кейс MD-05). Admin, любая работа. JobDetail автосохраняет — ничего не выбираем и не вводим, окно закрывается Esc. @prod-safe
import { test, expect } from '@playwright/test';
import { ADMIN_STATE, DEVICES, closeWithEsc, expectOpaqueModalOverDimmedPage, openJobItemsTab } from './modal-helpers';

test.use({ storageState: ADMIN_STATE });

test.describe('Модальные окна — непрозрачный фон (#b4c3bed5)', () => {
  for (const device of DEVICES) {
    test(`Price Book window from Job Details → Items is opaque over a dimmed page #b4c3bed5 ${device} @prod-safe`, async ({ page }) => {
      // Шаг 1: Job Details → вкладка Items
      await openJobItemsTab(page);

      // Шаг 2: кнопка «Price Book»
      await page.getByRole('button', { name: 'Price Book', exact: true }).first().click();

      // Шаг 3: окно «Price Book» непрозрачное, страница затемнена
      const dialog = page.getByRole('dialog', { name: 'Price Book' });
      await expectOpaqueModalOverDimmedPage(page, dialog);
      await expect(dialog.getByText('Select items from your price book')).toBeVisible();

      // Шаг 4: Esc
      await closeWithEsc(page, dialog);
    });
  }
});
